import json,collections,subprocess
from pathlib import Path
P=Path('series-catalog');R=P/'expansion'
read=lambda p:json.loads(p.read_text(encoding='utf-8'))
reports=[read(f)for f in sorted(R.glob('*.audit.json'))]
verified=[read(f)for f in (R/'verified').glob('*.json')]
lines=['# Estensione Seriale Shqip - verifica del 15 novembre 2026','','## Ambito e limiti','Una sola sezione `filma-shqip`, titolo visibile Seriale Shqip. Kafeneja Jone conservata senza ricensimento. Solo ID, metadati e pagine originali; nessun download di media o URL temporaneo persistente.','','Le raccolte NON sono dichiarate complete. Il censimento segue gli elenchi pubblici ufficiali scaricati con paginazione. Durata minima 15 minuti, titolo e numero controllati. La verifica della pagina video ha ottenuto '+str(sum(v.get('status')=='OK'for v in verified))+' risposte OK prima del blocco HTTP 429; '+str(sum('error'in v for v in verified))+' tentativi sono falliti. La verifica massiva e stata interrotta. Le altre pagine non sono state verificate individualmente. I cataloghi JSON distinguono `watch_metadata_checked` e `public_listing`. Una risposta OK non certifica la visione integrale o la riproducibilita su ogni dispositivo.','','## Ricerca ultima puntata','| Serie | Canale ufficiale | Puntata verificata | Pubblicazione osservata (Europe/Rome) |','|---|---|---|---|','| Shpija e Nuses | [ProMedia Production](https://www.youtube.com/channel/UCIWZkRKRowC5pqc3T_vfMAw) | [32](https://www.youtube.com/watch?v=qb4v5xggY7Y) | Martedi/venerdi circa 19:30 nei quattro campioni; episodio 32 con dati inizio/fine, precedenti senza dati broadcast |','| Gruaja | [Produksioni ANDRRA](https://www.youtube.com/channel/UCDdQzhTnTvgy32_3ruRbdkA) | [4](https://www.youtube.com/watch?v=0VfXtzT9D18) | Sabato, orari variabili: 21:27, 20:40, 20:23, 22:09; dati broadcast nei quattro campioni |','| Ne kerkim te Shpreses | [KURORA TV](https://www.youtube.com/channel/UCHX_nplfb4Cic1UhjC0dSrg) | [32](https://www.youtube.com/watch?v=A-s-5Nfe_xo) | Giovedi 20:00 nei quattro campioni; dati broadcast |','| Kojshillak | [Elsa Production](https://www.youtube.com/channel/UCHcJXpfCU3J6qzWUJBODBTw) | [9](https://www.youtube.com/watch?v=wNpJbPl36A8) | Campioni domenicali; 6 e 8 alle 19:00, 7 alle 21:31; 9 pubblicato 21:44 senza dati broadcast |','','I dati broadcast dimostrano una trasmissione programmata/avvenuta, non distinguono sempre premiere e diretta dopo la conclusione. Gli orari osservati non sono una regola futura e non governano la selezione. Canale, titolo, numero, durata e stato YouTube governano la ricerca. Attesa da -10 minuti, ricontrollo 30 secondi, data oggi solo Europe/Rome. La ricerca durante attesa controlla anche ID separati. Titolo reale al via per 5 secondi. Recupero Actions aggiunto ogni 15 minuti senza calendario inventato, mantenendo i cinque updater originali.','','## Raccolte e stato attuale','| Raccolta | Voci inserite (inclusi speciali) | Stato e scelte |','|---|---:|---|']
notes={
'o-sa-mire':'Serie originale e ritorno Reality separati. Fonti OSMGROUP e DigitAlb. Il ritorno 2024 e documentato da Klan; non assumiamo una conclusione definitiva. Stagioni non indicate nei titoli non ricostruite arbitrariamente.',
'cka-ka-shpija':'Fonti RTK e KlanKosova. Titoli fino alla stagione 13: non classificata conclusa. Numeri locali per le stagioni documentate; titoli senza stagione restano in Epizodat. Possibili repliche con numerazione diversa richiedono confronto editoriale.',
'egjeli':'Gjirafa: tre stagioni (1-30,31-60,61-80). STUPCAT aggiunge alternative ufficiali e raccolte 2016/HD separate; non fuse con il ritorno 2017. Film Egjeli 1/2, documentari, clip e Best of esclusi. Nessuna conclusione generale dedotta dal solo archivio.',
'schengen-visa':'Tre stagioni Gjirafa, numeri cumulativi originali. 58 episodi numerati; le 61 voci del sito comprendono anche contenuti esclusi. Il 58 Happy End chiude la stagione secondo la fonte riportata sotto, non prova assenza di futuri ritorni.',
'rrushe':'20 episodi nella stagione 1. La raccolta Bonus (29 voci) e interviste/clip: esclusa. Il riepilogo sito 49 contenuti non significa 49 episodi completi. Nessuna stagione 2 di episodi verificata.',
'njerez-dhe-fate':'RTSH Arkiv: 20 episodi originali, il 20 indicato i fundit. I ritorni cinematografici non diventano episodi 21+. Il canale Njerezdhefate che pubblica Mirenjohja non e una fonte pertinente solo per il suo nome.',
'fara-e-flliqt':'Fonte Fara e Flliqt Official. Stagioni 2-6 come nei titoli, numerazione ripartita conservata. Titoli con numerazione cumulativa in Epizodat; tre edizioni festive separate e senza numero inventato. Il 186 dice Fundi i nje epoke: indicazione di chiusura, non garanzia di nessun ritorno.'}
for d in reports:lines.append('| '+d['title']+' | '+str(len(d['rows']))+' | '+notes[d['id']]+' |')
lines+=['','Fonti di contesto: [ritorno O sa mire](https://klankosova.tv/abedini-dhe-arbnora-ne-ora-e-pasdites-sjellin-te-rejat-per-serialin-o-sa-mire-video/), [Rrushe ufficiale](https://video.gjirafa.com/rrushe), [Egjeli ufficiale](https://video.gjirafa.com/egjeli), [Schengen Visa ufficiale](https://video.gjirafa.com/schengenvisa), [Happy End](https://telegrafi.com/happy-end-shiko-episodin-e-fundit-te-schengen-visa/), [RTSH episodio 20](https://www.youtube.com/watch?v=Y5XpAa4uSbw), [ritorno Njerëz dhe Fate 3 al cinema](https://www.imalbania.com/historia-nuk-mbaroi-njerez-dhe-fate-3-rikthen-sagen-shqiptare-ne-kinema-nga-11-nentori/).','','## Lacune e alternative','I numeri seguenti sono assenti entro gli intervalli osservati: sono obiettivi di ricerca, non prova che una puntata sia esistita. Nelle stagioni con numerazione cumulativa non si contano come lacune i numeri appartenenti alle stagioni precedenti. Gli audit JSON conservano alternative ufficiali, scarti e motivi; le ricerche globali 0-10.json conservano anche risultati di terzi, non inseriti automaticamente.']
for d in reports:
 lines+=['','### '+d['title']]
 groups=collections.defaultdict(list)
 for row in d['rows']:
  if row['episode'] is not None:groups[row['group']].append(row['episode'])
 for g,ns in groups.items():
  missing=[n for n in range(min(ns),max(ns)+1)if n not in ns];lines.append('- '+g+': '+str(len(ns))+' episodi, intervallo osservato '+str(min(ns))+'-'+str(max(ns))+'; mancanti: '+(', '.join(map(str,missing))or 'nessuno entro questo intervallo'))
lines+=['','## Verifiche e riproducibilita','Script locali: research_expansion.py, collect_expansion.py, collect_expansion_gjirafa.py, verify_expansion_latest.py, verify_expansion_catalogs.py, build_expansion.py. Le estrazioni grezze in expansion conservano dati e ID originali; le risposte watch conservano titolo, durata, canale, date e stato. Nessun aggiramento del blocco 429. L URL Gjirafa schengen-visa restituisce 404; quello corretto e schengenvisa. Il primo handle DigitAlb non esponeva search: usato ID canale verificato nei risultati.','','Test Kotlin: selezione puntata, canale errato, durata, premiere, intervalli, ricerca esatta, conservazione Kafeneja e sezione unica. Test online sulle nove serie passato prima del blocco 429 (circa 1-3 secondi a serie). Test Python updater originale e recupero aggiuntivo passati. Compilazione debug locale. La transizione di una premiere realmente in corso e la riproduzione completa dei cataloghi non sono state provate end-to-end: non presentate come verificate. Nessun APK pubblicato.']
(P/'EXPANSION_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
# Confirm that the existing curated catalog has not changed.
cfg=read(Path('app/src/main/assets/config.json'));sec=next(s for s in cfg['sections']if s['id']=='filma-shqip')
old=json.loads(subprocess.check_output(['git','-C','film-discovery/remote','show','HEAD:config.json']))
oldsec=next(s for s in old['sections']if s['id']=='filma-shqip')
assert next(i for i in sec['items']if i['id']=='kafeneja-jone')==next(i for i in oldsec['items']if i['id']=='kafeneja-jone')
assert len(sec['items'])==17
for d in reports:
 for row in d['rows']:
  for e in row['sources']:assert e['official'] and e['url'].startswith(('https://www.youtube.com/watch?v=','https://video.gjirafa.com/'))
print('Catalog provenance, section and Kafeneja invariants passed')
